  三人で指輪探しの旅を始めて、どれくらい経ったか……
いくつか見付かった指輪は、新たな巫女が育つまでミトスが持つことになった。つまり、彼女の身の安全が、オルステラの安全に直結する状況。
共に在る騎士二人がミトスの身を最優先にするのは……まあ仕方のないことと言える。
しかしこのオルステラでは、二人は彼女に親愛以上の何かを抱いているようだ。そしてミトスはそれに気付いていない。
――危ういバランスの上に成り立つ、三人旅のある夜の一幕。

「ミトス」
「ミトスさん」
「……ええと…」
　ミトスは困っていた。左右から銀と金の騎士に選択を迫られているのだ。
　彼らの手には半分に割られたフルーツが乗っている。どちらも同じ果物だが、銀の騎士が持つ方は大ぶりで断面も瑞々しく、一口で十分喉を潤せるだろうと予測できるもの。対して金の騎士が持つ方は小ぶりではあるものの、その熟した見た目と芳香が食欲をそそる。こちらはきっと、うっとりするような甘さが疲れを癒やしてくれるだろう。
　どちらを選ぶのだ、と暗に問われているのである。
「私は農家さんの家で食べたから、それは二人が食べて…？」
　そう。この果物はミトスが依頼の報酬として受け取ったものだった。正確には報酬の一部である。宿で待つお仲間さんにも、と持たせてくれたのが、今彼らの手にあるものだ。
　「おいしいからぜひ」と、にこにこしながら勧めるミトスを見て、騎士二人は示し合わせたようにフルーツを割った。
　そして――冒頭のシーンになる。

「我らはそなたを待つ間に食事を済ませているのだ、この腹具合でオレンジ一つは少々多い。ロンドはまだ食べられるだろうがな」
