「……頼んだ料理の香りが凄まじく、食が進まなかっただけだ」
　後半を言わなければ、ミトスは銀の騎士から果物を受け取ったかも知れないというのに……。彼女に嘘をつきたくない、わかってもらいたいという、誠実さと承認欲求が混ざった結果――
