    keywords: `mt sz rd 第三者視点 ブレイク
  お昼を少し回って客足が落ち着いた頃、扉が開いて一人の青年が入ってきた。
　お目当てのテーブルをすぐに見付けられたようで、青年の足は迷いなくそちらへと向かう。
　そこには既に二人の客が座っていた。藍色の髪の娘と、白銀の髪の剣士だ。
　テーブルに向かって来る青年を見て、娘の方が声を上げた。
「ロンド！　良かった間に合って」
「こんにちはミトスさん、サザントスさん。本当に、間に合って良かったです」
　ロンドはテーブルにつくと、やれやれと言ったように荷物を下ろした。
「災難だったな」
「ええ、まさか橋が壊れているなんて思いませんでした。同行していた商人さんが別の道を知ってて助かりましたよ……と、あれ？　サザントスさん、美味しそうなもの食べてますね。この酒場にそんなメニューありましたっけ？」
　サザントスの手に乗っているのはナッツとドライフルーツの田舎パンだ。しかし上部がV字にカットされており、そこにはスライスされたにんじんとたまねぎのサラダが詰められている。ふわりと漂うドレッシングとオリーブの香りが食欲をそそるが、残念なことにロンドの元までは届かない。
「これはミトスが作ってきたものだ。…そんな目で見てもお前の分は無い、諦めろ」
「ええっ！？　そんな…！」
「ふふっ、大丈夫だよロンド。あなたのサンドイッチはこっちにあるから」
　ミトスはそう言って包みを取り出し、空いている皿に中身を乗せた。
「これは、もしかして“綿雪パン”ですか？」
「うん。ロンドのお気に入りだってお店の人から聞いたから」
　フレイムグレースのとあるパン屋の看板商品、それが綿雪パンだ。名前の通り真っ白でまんまるな見た目、そしてふわふわとした食感が子供に人気だが、『聖火守指長ロンドも好きらしい』との噂が駆け巡り、実は自分も好物なんですと告げる大人が増えたとか。
「ありがとうございます…！　美味しそうですね」
　にこにこと皿を受け取るロンドに威厳は見えない。
　一時期「どうすればサザントスさんみたいになれるだろう」と悩んでいたロンドだったが、サザントスの「私をなぞろうとするな」との助言を受け、悩みは払拭されたらしい。
　なお、サザントスが助言として言ったのか突き放すために言ったのかは定かでない。
　しかしロンドが聖火守指長として自分とは異なる層から支持を得ている様子を見て、一瞬だけ口元を綻ばせたところをミトスに見られている。彼女はそのことについて何も言わないため、サザントスも見られていない振りを貫いている。
　そんな二人に見守られる中、ロンドは「いただきます」とサンドイッチにかぶりついた。
　ハムとチーズが挟まれた綿雪パンのサンドイッチは二つあったが、瞬く間にロンドの腹に収まってしまった。
　食べ進めやすいように軽めの具材で作られていたこともそうだが、パンのほんのりした甘さに具材の塩気が引き立ち、食が進んだのだ。
　ふぅ…とひと心地ついたようにロンドは息を吐くが、食べたりない様子であるのは見て取れる。ミトスはくすりと笑いつつ、包みをもう一つ取り出した。
「もう一種類あるからどうぞ」
　今度置かれたのも綿雪パンで作られたサンドイッチだった。が、先程のものとは異なり少し膨らんでいる。中身がたっぷり詰まっているようだ。
「これは…オレンジ？」
「あとリンゴとブドウも入ってるよ。クリームはカスタード。さっきのよりボリュームがあるからね、食べ出があると思うよ」
「わあ…こちらも美味しそうですね、いただきます」
　一口食べたロンドは再び目を輝かせ、そんなロンドを見てミトスは実に嬉しそうに笑みを深めた。
「…ミトス、紅茶が冷めるぞ」
「へっ？　あれ、いつの間に？」
「ロンドが一つ目を食べ終わった頃だ」
　二人が話している間に頼んだらしい紅茶のポットがテーブルの真ん中に鎮座していた。ミトスの前には湯気をゆるく立ち上らせるカップも置かれている。ミトス自身に注いだ覚えが無い以上、サザントスが注いだのだろう。
　ありがとうございますと告げてカップに口をつけるミトスに、頷いて返すサザントス。彼の手にはまた別のパンがあった。
　いや、パンと言うより菓子に近い見た目である。
　パン自体は先程サザントスが食べていたものと同じ、ナッツとドライフルーツがたっぷり混ぜ込まれた田舎パンで作られたものなのだが、薄くスライスされた上に黄味掛かったシロップでコーティングされている。
「…ん？」
　一口齧ったサザントスは意外そうに瞬いた。
「あ…もしかして甘すぎました？」
「否、逆だ。見た目より甘さは無い、むしろ苦味と酸味が…」
　と言いつつもう一口。静かに咀嚼し、紅茶を飲み、最後に一口。
「……合うな」
「紅茶に、でしょうか？」
「確かに紅茶にも合うが、私の好みに。柑橘の爽やかさ、それに苦味と甘さが丁度良い」
「良かったぁ…。甘さ控えめで作りはしたんですが、それでも甘いと言われたらどうしようかと思ってました」
「酸味はレモンだろう？　この苦味は？」
「細かくしたレモンとオレンジの皮をシロップに混ぜたので、そちらかと。香りもその二つですね」
「なるほど」
　そう言ってサザントスは三切れ目に手を付けた。相当に気に入ったようである。
「ミトスさん、フルーツサンドごちそうさまでした！　とても美味しかったです…！」
「お粗末様でした。喜んでもらえて良かった」
「ところで、僕たちだけ美味しく頂いてしまってますが、ミトスさんは？　食べないんですか？」
「あー……実は、失敗したのとか綺麗にできなかったものとか食べてたから、あまりお腹空いてなくて。それに二人共美味しそうに食べてくれたし、もうお腹も胸もいっぱい」
　言葉通りに満足げな屈託のない笑顔に、ロンドもサザントスも何も言えず顔を見合わせた。
「ならば、せめてここの支払いは私が持とう」
「あっ、僕も同じことを言おうと…！」
「貴様は自分で払え」
「！？」
「い、いいよ二人共。私、自分で払うよ」
「それでは我らの立つ瀬がない」
「前回も今回もミトスさんからサンドイッチご馳走になってますからね。今回の支払いをサザントスさんが持つなら、僕は材料費を――」
「本当に大丈夫だって！　ええと…それなら二人に聞きたいことがあるんだけど…」
　何だ。なんです？　と同時に尋ねる聖火師弟に、ミトスはおずおずと切り出した。
「次はサンドイッチじゃなくてもいい？　その、クッキーとかパウンドケーキとか、お菓子でも…」
　二人は、やはり顔を見合わせ――
「もちろんです」
「そなたの負担にならぬのであれば」
　と、快く承諾したのだった。
 
 <ato><fund>◆ロンドのパン</fund>
　綿雪パン（はちみつ入りふあふあ白パン）カスタマイズ
　そのままでもおいしいほんのり甘い白パン。ふあふあしてるため、具材が重かったり汁気が多いとパンがへにょへにょになってしまう。サンドイッチにするには少し難しい。
　・パン自体に甘さがあるので、ハムとチーズという塩気のある食材を挟んだお食事サンドイッチ。もう一方が食べ応え重視なのでこちらは敢えて秒で食い尽くせるよう軽め。
　・食感を楽しめるよう、また食べ応えを感じられるよう、フルーツがゴロッとカットされたサンド。具はリンゴ、オレンジ、ブドウ。具材が零れないようにしっかりめのカスタードクリームで隙間を埋められている。
　（ブドウはウッドランドから、オレンジはコーストランドからの流通品。リンゴは寒いところでも育つ…筈）

<fund>◆サザントスのパン</fund>
　ナッツとドライフルーツ入りカンパーニュカスタマイズ
　パン自体に具材が多く楽しい食感なので、挟む具材はシンプルに。パンは固めでほのかな酸味があるため、サンドイッチにするにはロンドのパンとはまた違う難しさがある。
　・トマト、千切りニンジン、オリーブをドレッシングで和えたサラダサンド。ドレッシングはハーブを効かせて香り豊かに。パンを二つに分断して作るタイプのサンドイッチではなく、ころんとしているパンの上部をV字にカットして谷を作り、そこにサラダを詰めて作っている。
　（寒冷地でトマト…？と思ってしまったのでタマネギにチェンジ）
　・こちらは薄くスライスして提供。パン1個で5〜6枚は作れる。砂糖とはちみつとレモンのシロップでコーティングしたグレーズド。食べるのがサザントスなので甘さは控えめ。レモン皮、ロンドのフルーツサンドで余ったオレンジ皮を細かく散らして微かな苦味もプラス。パン自体のほのかな酸味に加え、グレーズドの甘さと柑橘の苦味で複雑な味が楽しめる。

<fund>◆ミトスの料理スキル</fund>
　美味しいサンドイッチを提供してるので料理上手っぽい印象を持たれていそうだけど、料理スキルは高くない。失敗したのは全部自分で食べて、ちゃんと成功したものだけを持って行っている。
　あまり手際が良くなく、ドレッシングやシロップも何度も作り直してどうにか完成に漕ぎ着けたもの。失敗作は相当数出てるので、本当にお腹いっぱい状態。本人は「みんなとごはん食べたかったなぁ…」とは思っている。二人共美味しいと言ってくれたので心ほこほこ。
　お菓子は練習の甲斐あって、割と安定して作れるようになった。`
