　呆れたような、落胆したような息が落ちる。こんな相手に負けたのかとでも言いたげだ。
「相棒が知らないとなると、あんたが知ってる話も正しいのかわからないな」
「安い挑発じゃな。しかし…よかろう。そうまでして知りたいと言うなら教えてやろうぞ」
　少しドキドキしながら続きの言葉を待っていると――
