    keywords: `sz Exジョブ if
  私が代役を引き受けたことは瞬く間に村中に広まった。そう広くはない村、しかも祭事に関わることなのだから、村中が関心を持っているのは理解できる。
　問題はその後だった。

「採寸…？」
「ええ。舞は難しいものではありませんが体力が要ります。あなたはひとりで大陸を回っていると言いますし、この点は大丈夫でしょう。ですが」
　伏せる舞手は眼光鋭く、発した。
「あなたと僕では体格が違うッ！」
「そうだな」
「………。」
「……？」
　話が見えぬまま数秒経ち―不意に舞手が「あっ」と息を呑んだ。
「そう言えば祭りについてお話ししていませんでしたね。あいたたた…」
「無理に体を起こすな、傷に障るぞ」
「ですが寝たままだと話しにくいですし」
　そう言って慎重に体を起こした舞手は、深くゆっくりと息を吐き出し、祭りについて簡単に説明し始めた。

　この祭りは狩王女、紳商伯、聖火神へと捧ぐもの。それぞれ一晩ずつ掛けてかの神へ舞を奉じ、最終日に三神への感謝と次の一年への祈りを乗せる。
　狩王女へ捧ぐ舞衣は赤。
　紳商伯へ捧ぐ舞衣は黄。
　聖火神へ捧ぐ舞衣は青。
　最終日に着用する舞衣は白。
　つまり舞手が代替わりする度に、新たな舞衣が四着必要になるのだ。

「待て。確か、祭りまであと三日と言っていなかったか？」
「そうです。祭りの初日、狩王女への奉舞まであと三日。なので――お願いしまーす」
「！？」
　舞手が部屋の入口に声を掛けると村の女衆が大挙して押し寄せ、気付けば私は彼女たちに囲まれていた。
「あら綺麗な騎士様！　髪もつやつやね！」
「それにとってもいい体してるわ」
「この肩、背、脚に腕……」
「うんうん、やっぱり今ある舞衣で合うのは無さそう」
「大仕事よー、寝られないわねっ」
　四方から絶え間なく囀る女性の声に、軽い眩暈さえ覚えた頃。
「おねえさんたちー、サザントスさんの採寸なら隣の部屋で頼むよ」
「あらそうだった！　ここだとあなたが休めないものね」
「みんな、移動するわよー！」
「な、待っ……」
　私の制止の声など届く筈もなく、押し流されるように隣の部屋へと連れて行かれたのだった。


「…まさか一晩で作り上げるとは」
　朝一番に届けられた赤の舞衣……の、試作。練習着としてのものらしいが、本番用と変わらぬつくりであると言う。
「舞衣自体はそう難しいつくりじゃないし、何よりあたしたちは服作って街に出すのが仕事だからね。それよりほら、着て踊ってみてくれない？　動きにくいとか、丈が足りないとか長いとか、直しが必要なら今日やんないと間に合わないんだ」
　部屋の外で待ってるから、と言い置いてその女性は部屋を後にした。
　彼女も夜を徹してこの服を作っていたのだろう、目の下にうっすらと隈が見え、部屋を出る背中には疲労感が漂っていた。
　私にとってこの村は任務の途中に立ち寄った仮宿でしかなく、祭りの可不可など瑣末なことで、今すぐ発とうと問題ない。むしろ任務を思えば発った方が良い。
　だが、捨て置けなかった。祭りを開けないかもしれないと、神々に感謝と祈りを捧げられないかもしれないと沈む空気を、払いたかった。
　舞の経験が無くとも務まるのならばと了承を返した時に広がった表情は――強く心に残っている。
　彼らに希望を差したのは私なのだ。最後まで務め上げねば。`
