　ミトスの言葉を聞いたエルフリックはそうかと呟き、中空に手を差し伸べた。その手を握るのに合わせ、室内の灯りがゆっくり落ちていく。
　終いには足元を照らす照明だけに落ち着いた。その灯りも湯気が柔らかく分散させており、薄暗さはあるもののぼんやりと周囲を視認できる程度には明るい。松明が所々灯る夜の露天風呂のようだ。
