　自身が零す吐息でエルフリックが高揚していることなど露知らず、中のモノがピクリと動く度に素直な反応を見せるミトス。そんな彼女を愛おしげに撫で、エルフリックもまた昂ぶりを抑えるために息を吐いた。
「ミトス…苦しくはないか？」
