　声に乗るのは全幅の信頼。
「だから…お願いします」
「――そなたは楽にしていなさい」
　体にかかるミトスの重さを感じながら彼女を抱きしめ、エルフリックはゆるやかに抽挿を始めた。
　湯に浸かっているから粘性を感じる水音はしない。その代わり、動く度に水面の波打つ音が二人の耳に届く。
