　そう尋ねるサザントスに、ハッと瞬いて意識を連れ戻すロンド。それでもすぐに続きを紡ぐことはせず、少し逡巡してからようやく切り出した。
「ええと…サザントスさんは、以前からミトスさんと共に任務に当たられていましたよね？」
