　隣部屋まで響きそうなほどの声で否定を口にしたロンドの顔は、依然赤い。
　それは本人もわかっているのか、すっかり冷めた紅茶を手に取り、あえてゆっくりと口に運ぶ。
　嚥下の微かな音が、二人の間に静かに落ちていく。
　それから、深く、ゆるやかに息をつき、少しだけ恥ずかしそうにしながら、ロンドは問いの理由を明かした。
「戦ってる時は気にならないんです。でも戦いが終わった時に気付くようになって、安心できて……。ミトスさんらしい、甘くていい香りだと思うんですが、どうやら香水や香り袋によるものではなさそうですし。もし彼女が自覚なく香りを纏っているのなら、今後宿の大部屋に泊まるのは控えた方がいいと伝えようと思ったんです」
　宿は個室を頼まない限り、利用者共同の大部屋に泊まるのが普通。隣のベッドを見知らぬ人が使うのも日常茶飯事だ。
　しかし、利用者のほとんどは複数人での団体客。ミトスのように一人だけというのは、なかなか珍しいのだ。ましてやそれが匂い立つ女性となると――同じ部屋に泊まる欲深い“獣”が牙を剥くかもしれない。
　宿側もそういった事件は起こしたくないわけで、利用者の選別を行うことがある。例えば、女性が一人で宿泊を希望する時は個室を勧める、というように。
　ミトスはそんな宿側の心理も理解した上で、基本的には大部屋を選んでいる。「他に個室を使いたい人・使うべき人が現れるかもしれない」という考えと、「万が一襲われても、たぶんどうにかできる」という自信からの選択だ。
　なお、一晩の宿なら教会も提供している。“選ばれし者”相手ともなれば、教会は快く泊まらせてくれるだろう。しかし当のミトスは「教会の宿は、本当に助けを求めている人のためのもの」と言って、宿屋での宿泊にこだわっている。
　単なる幸運か、それとも聖火神の加護か、これまでミトスが宿泊客に襲われたことはない。おそらくベッドのポジション選びも効いているのだろうが。
