　跳躍自体もそうだが、跳躍後の体勢を維持するために求められる筋力は、剣士のそれと異なる。それに、天空より定めた狙いを過たずに穿つための機を読む力とセンス。跳躍時、および襲撃時の補助を目的とした風使いの技術。襲撃後、次の行動に移るための体捌き。いずれが欠けてもこの技は成せぬ。
　一子相伝の奥義として伝えられても不思議ではない。私もクリスタルの力無しに習得しようとすれば、最低数年は費やすことになるだろう。
　世が窮している現状を思えば簡単には喜べぬが、こうして戦いの手数を増やせるのはありがたい。畏孵とやらが呼び寄せた異界の力、その身を以て味わわせてやろうではないか。
　しかし、身体の線に合わせたような鎧は防御面で不安を覚える。『ジャンプ』の邪魔をしないための工夫であるとのことだが、それならばこの頭装備は無い方が良いのではないか、と問えば――

「それは竜騎士の証のようなものだから」

　と返され外すことは叶わなかった。
