「心配せずとも必要な休息はとれている。…交代の時間までには戻る、異変があれば呼べ」
「わかった。気を付けて」
　心正しく素直な少年――セイル。“選ばれし者”であるこの少年の活躍を、私はよく知っている……のだが、セイルが言うにはこれも畏孵の断片の影響であるらしい。
　セシルが異界の者だと言うのはわかるが、私とオフィーリア、セイルとアグネアでまた出身世界が異なるのだと聞いた時は驚きを隠せなかった。
　厄介なことだ。違和感は異変を探るのに欠かせぬと言うのに、その違和感を抱かぬようにされては……最悪、誰も異変に気付けぬままこの世は混沌に呑まれてしまう。
　唯一、聖火神の指輪を持つセイルだけは断片の影響を受けぬようで、調査は彼頼みになってしまっている。ただでさえあの者はこの世の闇を払う任を託されていると言うのに、これ以上負担を増やすわけにはゆかぬ。
　……否、彼ではないのだったな。私が本来知る“選ばれし者”は。
「一刻も早く、大陸を元に戻さねば」
