　調査がセイル頼みとなるならば、その他の――例えば戦闘を、私が担えば良い。
　セイルは剣を使うが戦いをどこか恐れている節がある、逆に私は戦うのが仕事とも言える。得手不得手がはっきりしているのだ、互いに補えばいい。
「……この辺りで良いか」
　野営地から離れた林の中、葉の間から差し込む月の光だけが闇を僅かに遠ざけている。周囲に魔物らしき気配はない。
　軽く体をほぐしたあと、後端、中央、穂先近くと、持つ場所を変えながら手の中で槍を回してみる。己の一部と言えるほどではないが、見ずに取り回すくらいならば造作もない。こうして特に意識せずとも槍を弄べるのは“竜騎士”の力によるものだ。
　だが、この異界の力に頼りきるつもりは無い。槍を己の一部、腕の延長だと思えるよう鍛錬を積まなければ。
　槍は剣よりも間合いが広い、つまり狭い場所では振るうのに難がある。木々が乱立する中での鍛錬は良い経験となるだろう。
「―――ふっ！」
　試しに円を描くように振れば、槍は前方の幹を抉り、後方の幹は切っ先が掠るに留まった。狙い通りに振れている。
