「はぁっ！！」
　渾身の力で振り抜いたその軌跡を追うように風が荒々しく駆け抜ける。射線上にあった枝が数本、捻じ切られる音がした。
「ふむ。威力は悪くなさそうだ」
　しかし、その後何度か繰り返してみたものの、追撃の風を安定させられない。威力を高めることはできても、狙った方向に風が行くようにするのには時間が掛かりそうだ。
「…聖火を操るようにはいかぬな」
　昨晩に続き今日もまた新たな技を試してみたが、実戦で使うには練度が足りぬ。そして私たちには時間が無い。そのため、今は新たな技の習得に費やすよりも使える技を磨き上げる方が良さそうだ、という結論に落ち着いた。
「…………。」
　ふと見上げた頭上は葉に覆われ、その間から星が覗いていた。ここで『ジャンプ』をしたら、上空から着地点を定めるのは至難の業だろう。つまり、模擬訓練に適していると言える。
　今後、こういった場所での戦闘が起こる可能性は十分にある。その際“手”が一つ封じられるのは避けたい。
　上空から見定めるのが難しいならば……わかるようにしておけば良い。
　相手が魔物ならばその独特な気配を目印とすれば問題ないが、人間や異界の存在だった場合、あるいは魔物の気配が変質していたり気配そのものが薄い場合、正確に追えなくなるだろう。
　しかし私には、どのような場合においても確実に感知できるものが一つある。
「――青き炎よ」
　穂先に聖火を纏わせ、それを離れたところにある岩に向かって放つ。聖火は岩を取り囲み、絶えることなく揺らめいている。
　その様子を見届け、高く跳躍した。
　木々を越え、身体で空を切る感覚は存外心地好い。特に上昇から降下に移る際のふわりと浮く瞬間は、視界が一気に広がり、鳥にでもなったかのように錯覚する。
　あるいはこれが竜の見る世の姿か。
　そんな感慨に耽ることができるのもたった一瞬。次の瞬間には月光を背に、地上の聖火へ向かって急降下を始めている。
　威力を増すために風魔法で速度を上げ、一直線にその中心へと槍を突き刺せば――予想以上の音と地を揺るがす衝撃が響き、岩は砕け散った。
「ふむ、聖火を使うのは有効だな」
