　だって僕は灯火の守り手で、聖火守指長を継ぐのだから思い出さないと―――…、……？

　どうしてこんなことを思うんだろう。

　僕は…僕たちは、何を、“誰”を忘れて……？

「ッ……！」
　チリ、と紙片が焦げる感覚が走る。視界が頼りなく揺れて明滅する。まるで『思い出すな』と言われているようだ。
　そう思った瞬間、指先に聖火が灯った。何かに抗おうとするかのように、あるいは誘うように揺れている。その青い輝きを見ていると少しずつ落ち着いてきて、呼吸も楽になった。
　二、三度深呼吸して我に返ってみれば、聖火が灯っていた筈の手は優しく包みこまれていて、心配そうな目がこちらを見つめていた。
「大丈夫？」
「はい…。すみません、驚かせてしまいましたよね」
　ほどかれる手を少しだけ惜しく思いながら「僕もこんなのは初めてで」と笑って返すと、その人は目を伏せて考え込んでしまった。何か、迷っているようにも見える。
　声を掛けるのは憚られて、この人が次に何を言うのかを待った。
　互いの手の温もりと声の代わりに、聖堂の静けさと厳かな空気が僕たちの間を揺蕩う。それは決して気まずいものなんかではなかった。
　片側に燭台の灯りを浴びながら大聖火の光を背に負うその人の姿は、一枚の画のようで。でもどこか悲しくて。
　いったいこの人に何があったんだろうと思ったその時、彼女が目を開いた。
　そして僕をまっすぐに見据え、問うた。
「思い出したい？」
「え―…」
「無理に思い出そうとすればあなたが壊れるかもしれない、今の日々を信じられなくなるかもしれない。思い出せなくても平穏な日々は送れるし、もしかしたら思い出さない方が幸せかもしれない。それでも思い出したい？」
　深い水底に落ちていく小石のように静かな問いかけだった。
