「良かった。まあ、聖火騎士さんならこれぐらいで疲れたりしないか」
「すみません、少し考え事をしてました」
「ふふ…謝らなくていいのに。考え事なら私もするし。それに不安になるよね、どこに連れて行かれるのか判らなくて」
