「今は平和だよ。脅威を退けた後で、結束も固い。でもいつか時が経ち、各々が自身の利益のために動くようになったら……結束が崩れるかもしれない。守り手の誰かが、大陸を脅かす存在に変わるかもしれない。そうなってもあなたは、『戦いたくない』と剣を構えることすらしないの？」
