　喪いたくないと思うようになってしまったのは、いつからか。
　我儘らしい我儘など言ったことは無いのに、何故今こんなことを言うのだろう。何故、叶えられる我儘を口にしてくれないのか。
　そう思い拳を握る時点で、保ってきた距離などとうに消え去っているのだということに、リックはいつ気付くのだろう。あるいは、自覚しないよう見て見ぬ振りをしているのかも知れないが。
　そんな義父の葛藤に気付く筈もなく、ミトスはくるりとスカートを翻す。何に葛藤しているのかはわからずとも、困らせていることは察しているのだ。
「欲が深くてワガママで、遅れてきた反抗期もぶつかってるのに来てくれるなんて、この家の赤帽子さんは優しいです」
「そなたがそのような子ではないと知っているのだろう」
