　保護した直後を除けば、ミトスは眠りの深い子だった。使者の真似事をした最初の年以外、贈り物を置く前に彼女が目覚めたことは無い。だからといって今年も眠っていてくれるとは限らぬのだが。
　ミトスの枕元には彼女の“友人”がいる。彼女が級友から貰ったものや私が贈ったもので、その全てにミトスは名前を付けている。そのうちの一体、真っ白な犬の人形に小箱を持たせた。確か、名は……
