「ミトス」
　車内を覗き込むようにしてサザントスと話していたミトスが、車から一歩遠ざかる。そんな彼女を引き留めようとしてか、サザントスは咄嗟に彼女を呼んだ。
　一拍待っても続きが紡がれないことに首を傾げるミトスだが、サザントスも何故自分がミトスを引き留めたのかわかっていないのだ。続きを告げられる筈もない。
　深く呼吸する間に、何を伝えたいのか心の中を探り……、ようやく一つ掴み出す。
「そなたさえ良ければ、また――…」
　しかしサザントスはそこで言葉を切り、何でもないとばかりにゆるく首を振った。
　ミトスは研究所の職員ではない。研究に協力してくれているだけの、一般人なのだ。
　研究関係以外で負担になるようなことを頼むのは厚顔無恥というもの、彼女の親切に増長してはならない。
　そうして息を吐くサザントスを見て、沈黙を保っていたミトスは静かに口を開く。
　さわさわとそよぐ風が彼女の髪とスカートを揺らすが、声は攫われず、サザントスの元にまでしっかりと届いた。
「もし……また、お節介を許してくれるなら、今日みたいにごはんを作ってもいいですか？」
「………良いのか？」
「はい。今日ぐらいの量なら負担になりませんし、みんなに喜んでもらえて、とても嬉しかったので」
　言葉にも表情にも、サザントスを気遣って提案したような様子は無い。
