「あう……確かに、子供っぽいってよく言われます…」
「…責めたわけではないのだ。そなたのそうした純粋さが聖火に影響を与えている可能性はある。そなたはそのままで良い」
「そう、なんです…？」
「ああ。……さて、長々と引き留めてしまったな」
　チラリと目線を奥に向けたサザントスは、リックが門扉のすぐ向こうに来ているのを確かめた。
　挨拶をすべく降りようとするサザントスに、リックは「そのままで構わない」と告げ、ミトスの隣に並ぶ。
　リックは穏やかな笑みを湛えているが、その笑みに見合わない存在感がある。夜闇の中で光を放つようなそれは、彼一人で夜歩く程度なら灯りなど不要なのではないかという錯覚を引き起こす。実際に光を帯びているわけではないというのに。
「こうして直に言葉を交わすのは久しぶりだな、若き研究者よ」
「お久しぶりです、リック殿。御息女をこのような時間までお借りしてしまい、申し訳ありません」
