「はい、この時間まで残っていたのは私の意思です。皆さんいつもと変わらず親切で優しかったですし、彼らに非はありません」
「だそうだ。我が娘の願いを聞き入れた上、家まで送り届けてくれたそなたに感謝こそすれ、謝罪を求めることなどせぬ。顔を上げなさい」
