    keywords: `szmt sz×mt サザントス視点 選択後 手紙の日 ○○の日 【使いガラスの羽ばたきが聞こえた】
  　音がした方を見上げると、使いガラスが頭上を旋回していた。
　カラスは一声鳴いて近くの適当な場所に舞い降り、手紙を取るよう胸を張り目で訴えかけてくる。
　首から提げる筒には旅団のマークが刻印されている。ということはこの手紙は……
　手頃な餌を与えつつ差出人を確認すると、やはりミトスからの手紙だった。
　外では誰が見ているかわからない。ひとまず宿に戻ろうと顔を上げれば、任務完遂の空気を感じ取ったのか、カラスは誇らしげに鳴いて空へと羽ばたいていった。
　晴れ渡る青空を、黒点が翔けて行く。
　大競売が近付くこの時期、グランポートは多くの客と商人でごった返す。露店街でさえあの混みようだったのだ、会場前などいったいどれほどの人出となっていることか。
　混雑を気にせず翔けることができるというのは、さぞ気持ちが良いのだろうな。などと他愛ないことを考えつつ歩き、宿へ帰り着く。
　宿の主人への挨拶もそこそこに部屋へ戻り、手紙を開いた。露店街で調達した道具などはひとまず端に置いておく。
　アガペアは平穏な筈だが、何かあったのだろうか……
　薄く渦巻く不安を抑え、全体に目を通し要点を把握する。この際、綴られている感情は一旦無視し、緊急性の高さと事象だけを確認していく。
　聖火守指長となった頃に身につけた速読法だが…今回は必要なかったようだ。
　綴られていたのは、特に緊急性の無い内容――近況と待ち合わせについてだった。特に何かがあったわけではないとわかり、知らずに息が零れる。
　端に置いたままの道具をしまい手透きになったところで、改めて手紙を開く。そこには、こちらの様子を伺う言葉から始まる、彼女の胸中が記されていた。

<letter2>
サザントスさん

　グランポートの様子はいかがでしょう？　「グランポートは大競売が近付くと活気付く」――と以前エルトリクスさんから教えてもらいましたが、私は大競売に参加したことが無いので、どれほどの賑わいを見せているのか想像がつかず少しもどかしいです。
　グランポートが一年で最も賑わう、お祭り騒ぎな一日…。普段から賑わっているグランポートがお祭り騒ぎだなんて、考えるだけでわくわくします。そちらに合流するのが楽しみです。
　ただ、人出がすごいとも聞くので、何か事件が起きてやしないかと不安もあります。
　私も一緒に行ければ良かったのですが、アガペアの方も放っておけず……すみません。
　あなたにお任せした魔物討伐の方はどうでしょうか？　あなたが魔物に後れを取ることは無いと思いますが、怪我などはしていませんか？
　アタラクシアさんから分けてもらった回復薬があるので、合流したらお渡ししますね。

　こちらは用事も終わり、今は天候が落ち着くのを待っているところです。嵐が去らないとカラスも飛ばせないので、あなたがこれを読んでいるということは、私を乗せた船も出ている筈。
　アガペアからリプルタイドまで二日ほど、リプルタイドからグランポートまでがおよそ一日。なので、あなたがこれを受け取った三日後、早ければ二日後には合流できるんじゃないかと思います。
　合流場所なんですが、宿屋裏のカフェでどうでしょう？　オープンテラスで気持ちよさそうですし、どちらが先に待っていてもわかりやすいと思いますし。もし夜に着いたら、宿屋に向かいますね。
</letter2><p>
　手紙の一枚目はここまでだ。二枚目には少し気になることが書かれていた。</p>
<letter2><p>
　ところで……この手紙の他に紙片を受け取っていたら、そちらは気にしないでください。書き損じをカラスが勝手に持って行ってしまったんです。
　私が伝えたいことはこの手紙にあるのが全て。他は無視して大丈夫です……と、言いますか、見なかったことにしてくれるとありがたいです。

　それでは三日後、宿屋裏のカフェで会いましょう。</p>
</letter2>
<div class="letter-r"><letter2>ミトス</letter2></div>
<p>
「紙片、か」
　封の中にはこの二枚以外に何もなかった。
　手紙のこの書き方から、紙片とやらにはここに書かれていない何かを記していたのだろう。
　気にするな、と言われれば気になるのが人の性というもの。しかし彼女が見なかったことにしてほしいとまで願うのであれば、その願い通り追究せぬ方が良いだろうか。
「…有無を確かめるだけでもしてみるか」
　それで見付かれば内容を確認し、見付からなければ紙片のことは忘れよう。
「同封されていないのであれば――、ん？」
　窓を叩く音に続き、鳴き声が聞こえた。そちらに目をやれば、先程のカラスが開けろと言わんばかりに羽ばたいている。
「ちょうど良い、お前に用がある」
　中に引き入れてやればカラスは降り立てる場所を探して飛び回り、やがて椅子の背に落ち着いた。
　役目を果たしたカラスが戻ってくるということは、届け先を間違えたか――忘れ物をしたか。
「見せてもらうぞ」
　手紙入れをカラスの首から外し、蓋を開ける。筒の奥に白い欠片が落ちているのが見えた。
　数度振ると、紙片は木の葉のように舞い落ちた。しかし手の上ではなく、そのまま静かに机の上へ。
　そこに記されていたのはただ一言</p>
<letter2><p>
あなたに会いたい
</p></letter2>
<p>
「………。」
　これが書き損じとは、どういうことだ。
　記すのを止めた？　伝えたいことではなかった？　到底無視できぬこの言葉を？
「…待つのは、苦でなかったというのに」
　紙片を手に取り筆跡をなぞる。この一言の所為で待ち遠しくなってしまった。この三日、そなたに会えるまでの空いた時間をどう過ごせというのか。
「ふむ……そうだな、私の手紙も届けてもらうとしよう」
　一際高く、どこか嬉しそうにカラスが鳴く。
　さて、何から書くか。思えば任務も策謀も関係なく、ただ手紙を書くというのは随分と久しぶりだ。
　まずは依頼の完遂と私の無事を伝えるべきだろうか。それに、グランポートは彼女の想像を超える人出であること。待ち合わせ場所の了承。
　……共に大競売の様子を見て回る誘い――は、書かずとも良いか。彼女のことだから見て回りたいと言う筈だ。
「…………。」
　胸に温かく<ruby>灯<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>る<ruby>灯<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>が鼓動を大きくする。慣れぬ感覚ではあるが……悪くない。

「頼んだぞ」
　手紙を託し、カラスを空へと放つ。その姿は瞬く間に見えなくなり、潮の匂いがする風が木々を揺らしながら後を追う。
　ミトスは、あの手紙をどんな顔で読むのだろう。
　まずは私からの返事が届いたことに驚くだろうか。
　その表情を見られぬのは残念だが、伝えたいことは書いた。あとは当日まで待つのみ。
　手紙と紙片をしまい、もう一度外に出る支度を整える。
　カラスが戻る気配が無いことを確かめ、私は部屋を後にした。`
