    url: "https://erla.jp/fwfw_watage/novel/761697/827707/",
    keywords: `szmt sz×mt サザントス視点 選択式 キスの日 手紙の日 ○○の日 
  喧噪と雑踏に満ちる露店街を眺めて回る。
　未だ一部流通や交易にガ・ロハとの海戦が尾を引いていると聞くが、こうして巡る限りそんな様子は感じない。むしろ苦境を前に、奮起しているように見える。
　この逞しさはグランポート領主の手腕によるものか、それとも“商人”という人種の特徴か……

　グランポートが打撃を受けたと知った他地方の商人や商会は、こぞってこの地へ詰めかけた。駆け出しの商人は一旗揚げるため、狡猾な商会は販路拡大を狙って。
　押し寄せるその濁流を、グランポートは排さなかった。彼らが訪れた理由が必ずしも言葉通りでないことは承知の上で受け入れ、利権を掠め取ろうとする醜き欲すら呑み込んで……最後には己が一部としてみせたのだ。
　まったく呆れるほどに強かで逞しく――眩い。
　人々の活気溢れる表情を見届け、私はほんの微かな笑みを浮かべながら露店街を後にした。

　そうして宿屋がある地区まで戻ってきた時だ、私の耳に届く音があった。
 
 【娼館の娘たちの会話だ】
 【使いガラスの羽ばたきだ】`
