　規模としてはおそらく小さいものなのだろうけれど、花を愛でるために労力と手間を惜しみなく注がれた庭園なのだと一目でわかった。
「気に入ったか」
　声に振り向くと、テーブルの傍にサザントスさんがいた。彼の左手側にはシグナさんもいる。二人ともどこか穏やかにこちらを見ていた。
