  深い雪に覆われた祠を進み、その奥で揺らめく聖火に触れる。
　目を開けていると空間が揺らいだ時に眩暈がするから、目は閉じて、耳だけ澄まして。
　雪の静けさとは違う静謐さに包まれたのを感じて目を開ければ、今となっては見慣れた聖火神の領域に辿り着く。
　けど……いつもならそこにいる筈の姿が見当たらない。
　水鏡をそっと覗いてみるけれど、最近何かを映した様子を無さそう。地上の様子を見ている際に少し席を立った、ということではないみたい。
　ここではないのなら、大聖火の方かな？
　そう思って水鏡の間からアーチをくぐり、さらに奥へ。
　空気が一層澄んでいくのを感じて、無意識に呼吸を潜めてしまう。
　大聖火があるのは水鏡の間の奥、階段を上がった先の祭壇だ。けれどその清らかな気配は、階段下にいても感じられる。
　祭壇のある方を見上げれば、光が揺らめいているのが見て取れた。
　コツコツと響く靴音を聞きながら階段を上り切ると――予想に反してそこには誰もいなかった。人ひとり吞み込んでなお余るほどの大きさで、聖火が燃え盛っているだけだ。
　いったいどこに行ってしまわれたのだろう……。
　とりあえず一旦戻ろうと大聖火に背を向けた瞬間、寒気が背を駆け抜けていった。
「っ……今日の雪、すごかったからなぁ…」
　ぐっしょり濡れてしまっているケープを脱いで、溜息を一つ。これぐらいで風邪を引いたりはしないけど、早く温まりたい。そう、紅茶でも飲んで。
　ああ…でも、もし出掛けてしまっているのなら、今日は戻られないんだろうかと、少しだけ気落ちしながら水鏡の間へ引き返そうとした時――ぐっと後ろから抱き寄せられた。
