　今の私は戻ってきた聖火神に抱き寄せられたまま、お腹に彼の両腕が回っている状態だ。
　振り仰いで問うと、聖火神は優しく微笑んだ。
「体を震わせていただろう。すっかり冷え切ってしまっているではないか」
　腕に少しだけ力を籠められ、より密着するようになる。背中とお腹から聖火神の温かさを感じて、ゆるゆると力が抜けていく。
　そのまま彼の胸に頭を預けると、穏やかな声が聞こえた。
「疲れているのだな。今日はもう眠るがいい」
