「っ……！」
「そばにいて、ろんど……」
　寂しそうに告げられた言葉に心臓が跳ねた。夜闇の中で昂ったまま聞くのと、朝の薄暗い部屋で落ち着いたまま聞くのとではが受け取り方が全く違う。
