　彼女が教会に保護されて早数ヶ月、もはやこの光景も大聖堂の平和な日常と化しています。
　ミトスがお昼寝している間に（彼女のことはロンドに任せて）ふと聖火の間に寄った時なんて、大聖堂常連のおばさまたちが「あら、今日はミトスちゃんいないの？」とサザントスに声を掛けてきたぐらいです。“前聖火守指長”の肩書きより、“ミトスの守役”の方をすっかり認知されてしまっているサザントスなのです。
