    keywords: `書斎から本を取り戻ってくると、いつもの場所に座っていたミトスが隣に座り直した。
「どうした」
「ん…隣来ちゃだめでした？」
「駄目ではないが、珍しいと思ってな」
「サザさんの近くが良かったんです。もっと、近くがいい…」
　肩に乗る重みに胸が温かくなる。こうも素直に甘えてくるのは珍しい。
　が、ふと気付いた。
「………ミトス、そなたもしや青いグラスの方を飲んだのか」
「はい。美味しかったです」
「そなたのは白いグラスだ」
「あれ？　そうなんです？　でもどっちもお酒の香りがしてましたよ」
「なに？」
　テーブルに残された白いグラスを手に取ってみると、確かに酒の香りがする。ということは私は、誤ってどちらにも酒を注いでいた…？　らしくない失態だ。
「すまなかった、そなたは酒を苦手としているのに」
「苦手と言うより、飲むとすぐ寝てしまうので飲まないようにしているだけです。あのお酒は美味しかったから大丈夫！」
　美味かろうがすぐ眠ってしまう体質に変わりはないのでは…と思うものの、好みに合ったのは不幸中の幸いと言うものか。
　顔が仄かに染まっているのと上機嫌になっている程度で、呂律が回らぬほど酔っているわけではなさそうだな。この程度の酔い方ならば、体質に合う酒がわかれば酒場などで共に飲むことも――
「サザさんサザさん。大好きです」
「…………。」
　前言撤回だ。これを外に出してはいけない。
「好きです。大好きです。優しくて強いのも、誠実で優しいのも、時々ちょっと意地悪なのも、全部大好きです」
「…自分が何を口走っているか、わかっているのか」
「？　サザさんが好きです」
「ミトス、今日はもう眠れ」
「ええー、まだあなたの傍にいたいです」
　何を言っても好意が返ってくるのはどういうことだ。普段からこれの数割は素直に…
「何を言っているのだ、私は…！」
　駄目だ、思考が毒されかけている。
「サザさん何も言ってないですよ？　でも私、あなたの声も好きなので、たくさんお話ししてくれると嬉しいです」
「すまぬがそなたは少し黙っていろ」
「…………。」
　ぽふ、と自身の両手で口を塞ぐミトス。発言が妙なだけで、こちらの言葉を聞こうとする意識は残っているようだ。しかし先程は部屋に戻るよう言っても聞かなかったと言うのに――…いや、そうか。あれは……。
「ミトス、こちらに」
　差し出した手に乗せられた彼女の手は平時より少し熱い。そのままその手を引いて彼女の部屋へ向かうが、嫌がる素振りや渋る様子はない。
　やはり一人になりたくない…私といたい、と言うことのようだ。普段そうした意思を示すのは私の方で、彼女は私を受け入れ、満たしてくれるのだが、逆の立場になるとこうも心が浮つくものか。
　ふと様子を窺ってみれば、彼女はふらつくことなく、手を引かれるまま機嫌良さそうに何かを口遊んでいた。
「サザさんといっしょ、いっしょ、うれしいなー、ふふふん」
　可愛い――ではなく…！
　視線に気付いたミトスは目が合うと柔らかに破顔した。母の腕の中で屈託なく笑う赤子のように。
「サザさんの手、大きくてあったかくて、好きです」
「……そうか」
「今日はいつもよりあったかいですね、ふふふ」
「………。」
「サザさん、すきです」
「聞こえている」
「ずっとずっとだいすきです」
「…口を閉じろ。舌を噛むぞ」
「わあっ？」
　抱き上げ、ベッドに下ろす。
　ぼんやりとこちらを見上げる視線を感じながら毛布をかけてやり、少しだけ頭を撫で、心地よさそうに目を閉じたのを見届ける。
　そして背を向けた瞬間――
「…触れてくれないんですか？」
「！？」
　振り返るとミトスが体を起こすところだった。
「酔った私じゃだめですか…？　触れたくない…です？」
「酔っているからこそ、触れるわけにゆかぬ。私の過失であることだしな」
「かまいません。私は…あなたにふれてほしいです…」
「っ……」
　普段ならば、滅多に無い彼女からの誘いを断るなどしない。だが今は
「酔いに乗じて触れるような下衆に成り下がりたくはないのだ」
「そんなあなただから大切で、すきで…、ふれてほしいとおもうんです」
　まっすぐに見つめられ、視線を逸らせない。逸らしたくない。
「サザさん……―触れて？」
「ッ――！！」
　己を差し出すようにこちらへ両手を広げた彼女に一瞬だけ眩暈がし、誘われるまま強く抱きしめ諸共ベッドに倒れ込んだ。
　嬉しそうに熱い息を零し、胸にすり寄る彼女を愛おしいと思う。
　薄いシャツの向こうに柔らかな肌を感じながら、ゆっくりと背を撫でる。
　そのまま……どれほど経ったか。おそらく数十秒程度だろうが、腕の中から安らかな寝息が聞こえてきた。
「……眠ったか」
　起こさぬように安堵の息を吐く。
　蕩けた目と舌足らずな言葉から眠気が来ているのだとわかったのは良いものの、本当に眠るかは五分五分だった。寝てくれなければこちらが危うかったのは事実。
「今後も、そなたに酒は飲ませられぬな」
　彼女が好きだと言った手で頭を撫でる。
　感触もそうだが、こうして撫でた時の反応が好ましく、つい撫でてしまう。さすがに眠っている時は無反応だろうが――
「……サ…さん……、すき…で……」
「………。」
　眠っている間もそうした言葉を囁いてくれるとは、器用なものだ。
「起きたらまた聞かせてくれ」
　額にキスを落とし、静かに部屋を後にした。

―――……

　リビングに戻り、グラスに残る酒を飲む。
　香りの甘さに比べて口当たりが軽く飲みやすい。酒独特の喉を焼くような感覚は控え目で、酒を飲み慣れない者にも受け入れられやすそうだ。実際、彼女の好みには合っていたようであった。この酒に合わせるならばナッツやドライフルーツが良いだろう。
　もう一口含み、舌の上で転がす。この先もしばらく彼女に酒を飲ませる気はないが、好みを把握していて不都合は無かろう。
　果実の甘さが香り立つ、後に残らぬ清爽な吞み口……。ヴァローレの守護者がこれを知ったら新作を作るだろうか。もしこれに近い新たなワインができるのであれば飲んでみたい。
　それにヴァローレ産のシロブドウジュースは彼女の好物の一つ。いつかワインの方も飲んでみたいと言っていたし、作られた新作が好みの風味となれば喜ぶに違いない。
「……何を考えているのだろうな、私は」
　新作が作られることなど、今はまだ、ただの夢想でしかないと言うのに…想像の翼が止まらぬ。まさかこの程度の酒で酔ったわけでもあるまいに。
　最後の一口を呷り、グラスを片付けた。自室へ戻る途中にも、いつか彼女と共に酒を飲めたらと言う思いが浮かぶ。
　あの状態のミトスとも酒を飲めぬわけではないが、私の理性が持たない可能性が高い。私も飲んでいるなら尚更だ。
　いつか彼女が眠らず、平時を保てる酒に出会えたら。あるいは彼女の体質が和らいだなら。その時は共に酒を飲もう。
　微酔い気分で、互いに他愛ない話をしながら過ごす穏やかな夜――。その光景を思い描きつつ、私は今日と言う一日を終えた。`
