    keywords: `『誰だこいつ』
「……ミトス、それは？」
「猫さんです」
「それは見ればわかる。何故、猫を連れている」
「お散歩中に魔物に襲われてしまったのだそうです。前足をケガしてうまく歩けないから、安全なところまで連れて行ってほしいと」
　その時、ミトスの腕に抱かれた猫が訴えるように鳴き始めた。暴れる様子は無いが、何か急かしているようにも見える。
「え、追ってきてる？　猫さん、魔物に追われるようなものでも持ってるの？」
『実は…ラットキンの宝置き場、荒らして来ちまって』
「それは…追われても仕方ない、というかよく逃げてこれたね…？」
　もしや私は今、夢を見ているのだろうか。ならばもう少しまともな夢であってほしいものだが…。
「ミトス、そなたは猫の言葉がわかるのか？」
「はい。あれ？　サザントスさんには聞こえてないんですね？」
「ただ鳴いているようにしか聞こえぬ」
「それなら…手を出してください」
「？」
　言われるまま差し出した手のひらに、聖火神の指輪が乗せられる。
『あっ、おい！　いいのかよ、そいつに渡して！！』
「！？」
「わ、猫さん暴れないで…！」
『こいつ、どっかぼんやりしてるなって思ってたけど、普通指輪渡すか！？　信じらんねえ！』
「ね、猫さん落ち着いて、大丈夫だから…！」
『フン、どうだか。おいおまえ！　その指輪を悪いことに使おうってんなら、オレが許さねえからな！』
「この猫は指輪が私の手にあるのが相当気に入らぬようだ」
『当たり前だろ！　こいつ、ぼんやりしてるし頼りなさそうだし弱そうだし優しいだけが取柄みたいな“選ばれし者”だけど、それでもおまえが持つよりマシだ！　さっさと――』
「………。」
『…なんだよ』
「貴様がこの者に抱いた印象はわかった。それを改めさせるつもりも無い、が…」
　無性に、腹立たしい。
「この者を、見かけで判断するな」
『ッ…』
「猫さんが私をどう思ってるか言ってるんですか！？」
　こちらの剣呑な空気が伝わっていないのか、ミトスが弾んだ声を上げる。
「なるほど、指輪を持つ者にだけ聞こえるのか」
「はい。なので今あなたと猫さんがどんなことを話していたのか、私にはわからないんです。猫さん、何て言ってました？」
「…さてな」
　輝く瞳を向けられ、咄嗟に何も返せなかった。ヒューゴやロンドであればうまく返せただろうか。…いや、ロンドは私と同じく言葉に詰まるか、下手に誤魔化して彼女に気取られるかだな。
　指輪の力がわかったところで、先程とは逆に、彼女に手を出すよう告げる。差し出された右手をひっくり返し、その指に聖火神の指輪を嵌める間、猫はこちらの手元を静かに見守っていた。
『やっぱ“選ばれし者”の手にある方が聖火神も落ち着くみたいだな』
「そう？　あ、でも確かに、いきなり“手”が変わったら聖火神もびっくりするかも知れないね」
『はー？　やっぱお前ぼんやりしてんな』
「それは時々言われるよ。でもきみを安全な場所に連れて行くことぐらいならちゃんとできるから、安心して」
　傍から見る分には、彼女が笑顔で猫と話している和やかな光景だが、この猫の口振りを知ってしまった今、そう穏やかな心持ちではいられない。棘のある言葉を聞いて、傷付かなければ良いのだが…。
　猫の言葉を気にするな、と言うは易い。彼女もおそらく「そうですね」と応じる。しかし……そうすれば今度は、私に気付かれぬよう傷を隠すだろう。ならばいっそ、猫をどこかにやるまで私が指輪を預かっている方がいいのでは――
『…おまえ、こいつが大切なんだな』
「え」
「…ん？」
『おまえからは闇のにおいがする。けど、“選ばれし者”を大切にしてるってことは、闇の者じゃないのか』
　猫が私に何か言っているが、生憎と指輪は彼女の手だ。ただ鳴いているようにしか聞こえない。
「そっか、だからサザントスさんに指輪を渡した時、きみはあんなに慌てたんだね」
「猫は何と言っているのだ？」
「あなたから闇のにおいがすると。でも“選ばれし者”を大切にしてるのなら、闇に属する者じゃないんだな、とも言っています」
「！」
「猫さん。サザントスさんは確かに闇の力も使えるよ。でも闇の力を使う人みんながみんな、悪い人ってわけじゃないの」
『えー？』
「本当だよ。それにこの人は――」
　ミトスが何か言いかけたその時、前方の森から大量のラットキンが姿を現した。連中はこちらを見て喚き、弓や槍を振り上げつつ向かってくる。
「――サザントスさん。私が攪乱するので、一掃をお願いできますか」
「任されよう」
「きみはここにいてね。出て来ちゃだめだよ」
　猫が茂みに隠れるのを見届けたミトスは踵を返し、ラットキンの群れに突っ込んでいった。猛る魔物は感情のままに得物を振り回して迎え撃つが、森の鼠ごときに彼女を捉えられる筈もない。
　疾走と跳躍を繰り返し、舞うように連中を釘付ける。
　町の者たちは、彼女が戦う姿を想像するのは難しいと言う。戦うとしてもサポートを主とし前に出ることは無いだろうと。短剣を携えているとはいえ、柔和な彼女しか知らぬのであれば無理からぬことだ。
　それはどうやら獣も同じらしい。茂みから顔だけ覗かせた猫は、敵に囲まれている彼女と動かぬ私とを交互に見て、鳴いた。
『おい、いいのかよ』
「…指輪が無ければわからぬと言っただろう」
　おそらく、お前は行かないのか、とでも言っているのだろうが。
「ここからで十分だ。あまり近いと彼女を巻き込む」
　だが…そろそろ頃合いか。
　剣を構え、一点に狙いを定める。
「“青き炎は我が魂、我が守り人なり”――」
　刀身に聖火を纏わせ、何層にも重ねていく。炎の大きさは変えぬまま、密度と純度だけを上げていく。
　十分に高まったその瞬間
「サザントスさん！」
「退け！　ミトス！」
　彼女の合図とこちらの合図が重なり、聖火が最大の輝きを放つ。
　射線上に固められたラットキンの一団はその光でようやく聖火に気付いたが、もう遅い。
「――邪悪を焼き尽くせ！！」
　振るった剣から炎が迸りラットキンに迫る。はじめは剣閃の形そのままで決して大きくはなかった炎は、空を走る間に群れをも呑み込む大火となり、連中は声を上げる暇もなく灰と消えていった。
　聖火が焼いた後の草花には何も変化がなく、ここで魔物の群れが焼き尽くされたのだとは誰も気付かぬだろう。
　その僅かに残る灰の跡をさくりと踏み分けながら、ミトスが戻ってくる。
「お疲れ様です、サザントスさん」
「ミトス、怪我はないか」
「おかげさまで。…ええと、猫さんは」
『ここだ』
「良かった、無事だね」
「では戻るか。…期せずして依頼も果たせたことだしな」
「ですね」

　討伐依頼を果たしたと伝えると、町の者は大げさなほどに驚き、喜んだ。被害状況は聞いていたが、我らの思うより根の深い問題だったようだ。
　そして猫は…宿の主人が引き取ることになった。ミトス曰く、猫も了承したと言う。
　今は宿の一室で彼女が別れを惜しみつつ、猫の治療をしている。
「はい、これで大丈夫。でも治りきるまであんまり走ったりしないようにね？」
『仕方ねえな』
「手慣れているな」
「ふふ、キャットリンの友だちがいるから、ですかね。手持ちの薬草で処置できる程度で良かったです」
　猫の頭をそっと撫でながら、ミトスは目を閉じた。
「早く傷が治りますように。きみが、この町の人たちに愛されますように…」
『……おい、あいつと話しさせろ』
「え？　うん、わかった。…サザントスさん」
「なんだ」
「猫さんがお話ししたいみたいです」
「私と？」
　言いながら、差し出された指輪を受け取る。猫はこちらを見つめ、出し抜けに告げた。
『おまえ、あんまり余裕かましてると、こいつ他のやつに取られるぞ』
「………、何を言っている？」
『あれ、そういうんじゃないのか？　ふうん……？』
　猫は尾を揺らしながら、真意を量るように目を逸らさない。しかし唐突に向きを変え、彼女の胸に飛び込んだ。
「わっ！？　だめだって、あんまり激しい動きしちゃ…！」
『あんたならキャッチしてくれるって思ったし、柔らかいし温かいし』
　優しく抱えるミトスに、猫は喉を鳴らして甘えている。……この猫、どういうつもりだ。
「…ふふ、急に甘えん坊さんになりましたね。お話終わったんです？」
「さてな、何が言いたかったのかわからぬ」
「そうなんですか？」
　私の手から指輪が離れるのを見て、猫は再び鳴きだした。
　いったい何を話しているのか、黙って聞いていたミトスは最後に笑いを零し、「待ってるね」と返した。
　…何をだ。そして何故あの猫は勝ち誇った顔で私を見ている。指輪はまだ返さぬ方が良かったか？　否、私が手放さなければあの猫は話し出さなかっただろう。ならばミトスに何を話していたのか聞いてみるか…？　しかしそれは何か、こう、釈然としない。
「………。」
「サザントスさん？　難しい顔してますけど、どうかしたんですか？」
「…ミトス」
　手招くと彼女は素直に応じ、首を傾げた。その胸にはまだ猫が抱かれ、猫はこちらに警戒した視線を送っている。
　特に何をしようと思って呼んだわけではない。強いて言うならば“なんとなく”だ。
　だが「何でもない」と帰すこともまた、“なんとなく”できぬ。
　結果、私が出した答えは――
「わっ」
「………。」
「あ、あの、サザントスさん…」
　戸惑いの声も聞かず、そのまま彼女の頭を撫でる。さらりとした髪が滑る感覚は思いのほか心地好く、その内に彼女が羞恥混じりの嬉しそうな笑みを浮かべているのが見え、胸に渦巻いていた靄は霧散した。
　手を離したあともふわふわと柔らかに笑っているものだから、もう一度撫でてやろうかと思ったくらいだ。
「猫さんじゃなくて私で良かったんですか？　猫さん、野生の子ですけど毛並み良い方ですよ？」
「そなたが良い」
「あら、振られちゃったね猫さん」
『別にいいし。それより歩きてえんだけど』
「え、下りるの？　無理しないようにね」
　ミトスが猫を床に下ろし、その歩みを見守っていると、室内にノックの音が響いた。
「お二人とも、食堂の準備が整ったのでお越しください！　みんな待ってます！」
「…ささやかなものでかまわぬと言ったのだがな」
「みなさんの感謝の気持ちがそれだけ大きいということなんでしょうね。ありがたく頂きましょう？」
「では行くか」
　扉を開ければ猫が隙間からするりと抜け出し、先導するように先を歩いて行く。時折こちらを振り返るところを見ると、本当に先導しているつもりなのかも知れない。
「また今度この町に来た時、あの子が看板猫になってる姿が想像つきますね」
「…そうだな」
　その時には彼女ではなく、宿屋の娘の胸を居所としていてほしいものだ。`
