【アクセ】
細いティアドロップタイプの耳飾りを両耳に着けている。が、正面からは髪で隠れて見えない

【武器】
短剣：軽くて丈夫で女性でも取り回しやすい。武器屋に下取ってもらい、より良いものを購入するなどしている。
弓：折り畳み式。目覚めた時から持っていたもの。その機構は魔導機に近く、現在のオルステラでは再現及び修復不可能。ミトスが自身の記憶を探るための唯一の手がかりと言える。

【指輪】
右手薬指に嵌めている。
指輪のことは『なんかすごいもの』くらいにしか思っていなかったが、旅が進むにつれ『たくさんの人と出会わせてくれた大切なもの』と思うように。

【カラーリング】
全体カラーリングまとめはこちらをどうぞ。

【口調】
一人称は「私」。
基本的に敬語。仲良くなったり心的余裕が無い時は敬語が崩れる。

【性格】
圧倒的且つ無意識の利他主義。他者の心の機微に敏いが自分のことには疎く、サザントスから「己を他人の外に置いている」と言われてようやく自覚した。
恋心さえ、仲間に指摘されるまで気付けなかった。
“他者の死”に強い拒絶を示し、敵であろうと命を奪うことは最後まで躊躇う。が、一度決めたら躊躇わない。
平時はのんびりふんわり。
大抵のことは「大丈夫だよ」と言って包み込む。その包容力について「お姉さんみたいですね」とはロンド談。

【好きなもの】
誰かの笑顔（知り合いでもそうでなくても）

【苦手なもの、嫌いなもの】
お酒が苦手、すぐ酔って思考が回らなくなる。エール一杯で眠ってしまう。
苦しみや悲しみはもう十分。


【その他】
指輪を手に目覚めるより前の記憶がない。年齢がわからないのもこのため。記憶を失った中で唯一心に残っていたのが名前だった。
とても強い祈りの力を持っている。祈る時に一切の雑念が混じらず、雑念を遮断して祈る姿勢に入る速さが尋常ではない。

―――――――――――――――――――――
蛇足おぶ蛇足

【パラメータ：高い順】
属攻＞会心＞SP＞属防＞回避＞速度＞HP＞物防＞物攻
　※盗賊ジョブとしては遅い方だがラース相手に先手を取れるくらいの速度はある
　※弱い物攻を高い会心と手数で補う
　※ミトス自身は魔法を使えないが、旅の中で属攻を活かせるアビリティを身につける

【アビリティ傾向】
短剣と弓。
デバフは速度ダウンと物攻属攻ダウンを修得。

